-- Generated by the full-seed builder; part of the bigger presentation data set.

-- Auctions from the cards shops kept in hand (05b stock_hand rows marked 'เก็บไว้ลงประมูล'):
-- live ones with real bidding wars, some ending within the hour, finished ones that were paid,
-- one waiting for payment, unsold and cancelled ones.
DO $$
DECLARE
    card    record;
    a_id    bigint;
    b_id    bigint;
    lead_id bigint;
    i       int := 0;
    nbids   int;
    price   numeric;
    start_p numeric;
    step    numeric;
    started timestamptz;
    ends    timestamptz;
    scen    text;
    bidder  bigint;
    last_b  bigint;
    bidders bigint[];
    t       timestamptz;
    cost    numeric;
    anchor  timestamptz := (SELECT anchor FROM seed_clock);
    plan    text[] := ARRAY['live', 'live', 'ending', 'live', 'sold', 'live_quiet', 'awaiting', 'live', 'ending', 'sold',
                            'unsold', 'live', 'sold', 'cancelled', 'live', 'ending', 'sold', 'live_buynow'];
BEGIN
    SELECT array_agg(user_id ORDER BY username) INTO bidders FROM seed_new_buyer;
    FOR card IN
        SELECT lu.id, lu.seller_profile_id, lu.catalog_variant_id, lu.condition_code,
               coalesce((SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY l.price) FROM listing l
                          WHERE l.catalog_variant_id = lu.catalog_variant_id AND l.grading_company IS NULL), 800) AS market
          FROM listing_unit lu
         WHERE lu.status = 'IN_STOCK' AND lu.unit_note = 'เก็บไว้ลงประมูล'
         ORDER BY lu.id
    LOOP
        i := i + 1;
        scen := plan[1 + (i - 1) % array_length(plan, 1)];
        price := card.market;
        start_p := greatest(50, round(price * 0.45 / 10) * 10);
        step := CASE WHEN price < 1000 THEN 20 WHEN price < 5000 THEN 50 WHEN price < 20000 THEN 100 ELSE 500 END;
        IF scen IN ('live', 'live_quiet', 'live_buynow') THEN
            started := anchor - make_interval(hours => 6 + i % 40);
            ends := anchor + make_interval(hours => 8 + (i * 7) % 90);
        ELSIF scen = 'awaiting' THEN
            started := anchor - make_interval(days => 4);
            ends := anchor - interval '3 hours';
        ELSIF scen = 'ending' THEN
            started := anchor - make_interval(days => 3);
            ends := anchor + make_interval(mins => 25 + (i * 13) % 80);
        ELSE
            started := anchor - make_interval(days => 5 + i % 20);
            ends := started + make_interval(days => 3);
        END IF;
        UPDATE listing_unit SET status = 'ON_AUCTION', updated_at = started WHERE id = card.id;
        INSERT INTO auction (auction_number, seller_profile_id, listing_unit_id, catalog_variant_id, condition_code,
                             starting_price, bid_increment, buy_now_price, current_price, bid_count, bidder_count,
                             started_at, original_ends_at, ends_at, status, created_at, updated_at)
        VALUES ('AUC-2026-' || (2000 + i), card.seller_profile_id, card.id, card.catalog_variant_id, card.condition_code,
                start_p, step, CASE WHEN scen = 'live_buynow' OR i % 5 = 0 THEN round(price * 1.25 / 10) * 10 END,
                start_p, 0, 0, started, ends, ends, 'LIVE', started - interval '10 minutes', started)
        RETURNING id INTO a_id;

        nbids := CASE scen WHEN 'live_quiet' THEN 0 WHEN 'cancelled' THEN 0 WHEN 'unsold' THEN 0
                           ELSE 3 + (i * 5) % 14 END;
        price := start_p; lead_id := NULL; last_b := NULL;
        FOR k IN 1..nbids LOOP
            bidder := bidders[1 + (i * 7 + k * 3 + (k % 2) * 5) % array_length(bidders, 1)];
            IF bidder = last_b THEN bidder := bidders[1 + (i + k * 11) % array_length(bidders, 1)]; END IF;
            price := CASE WHEN k = 1 THEN start_p ELSE price + step * (1 + (k + i) % 3) END;
            t := started + (least(ends, anchor) - started) * (k::numeric / (nbids + 1));
            INSERT INTO auction_bid (auction_id, bidder_id, amount, status, idempotency_key, created_at)
            VALUES (a_id, bidder, price, 'ACTIVE', 'seed-auc2-' || a_id || '-' || k, t)
            RETURNING id INTO b_id;
            lead_id := b_id; last_b := bidder;
        END LOOP;
        IF nbids > 0 THEN
            UPDATE auction
               SET leading_bid_id = lead_id, current_price = price, bid_count = nbids,
                   bidder_count = (SELECT count(DISTINCT bidder_id) FROM auction_bid WHERE auction_id = a_id),
                   first_bid_at = (SELECT min(created_at) FROM auction_bid WHERE auction_id = a_id)
             WHERE id = a_id;
        END IF;

        IF scen = 'sold' THEN
            UPDATE auction SET status = 'SOLD', winner_id = last_b, winning_amount = price, closed_at = ends WHERE id = a_id;
            PERFORM pg_temp.seed_auction_order(a_id, last_b, true, ends);
            UPDATE listing_unit SET status = 'SOLD', sold_at = ends WHERE id = card.id;
            cost := pg_temp.cost_issue(card.seller_profile_id, card.catalog_variant_id, card.condition_code, 1, ends);
            INSERT INTO inventory_movement (seller_profile_id, listing_unit_id, catalog_variant_id, condition_code,
                                            movement_type, quantity_delta, unit_cost, created_by, created_at)
            VALUES (card.seller_profile_id, card.id, card.catalog_variant_id, card.condition_code,
                    'SALE', -1, cost, pg_temp.seller_user(card.seller_profile_id), ends);
        ELSIF scen = 'awaiting' THEN
            UPDATE auction SET status = 'AWAITING_PAYMENT', winner_id = last_b, winning_amount = price, closed_at = ends,
                               payment_due_at = ends + interval '24 hours' WHERE id = a_id;
            PERFORM pg_temp.seed_auction_order(a_id, last_b, false, ends);
        ELSIF scen = 'unsold' THEN
            UPDATE auction SET status = 'UNSOLD', closed_at = ends WHERE id = a_id;
            UPDATE listing_unit SET status = 'IN_STOCK' WHERE id = card.id;
        ELSIF scen = 'cancelled' THEN
            UPDATE auction SET status = 'CANCELLED', cancelled_at = started + interval '2 hours',
                               closed_at = started + interval '2 hours' WHERE id = a_id;
            UPDATE listing_unit SET status = 'IN_STOCK' WHERE id = card.id;
        END IF;
    END LOOP;
END;
$$;
